#!/usr/bin/env node
'use strict';
// Cache-free, terminal-only S10 WIN proofs -> S9 WIN -> S8 WIN.
// All children are regenerated by independent 3x3 and 4x4 integer geometries.
const fs=require('node:fs'),path=require('node:path');
const g=require('../n11-gap6-terminal-20261019/verify_js.js');
const independent=require('../n11-s9-shared-plan14-eleven-win-20261027/verify_fast.js');
const base=require('../n11-s5-pair-cover-20261026/audit_remaining_matching.js');
const lossCert=require('../n11-s9-shared-loss-pruning-20261027/verify.js');
const EXP=path.resolve(__dirname,'..');
const need=(ok,msg)=>{if(!ok)throw Error(msg);};
const read=p=>fs.readFileSync(path.join(EXP,p),'utf8');
const keys=p=>read(p).trim().split(/\s+/);
const same=(a,b)=>a.size===b.size&&[...a].every(h=>b.has(h));
const raw=()=>fs.readFileSync(path.join(__dirname,'certificate.tsv'),'utf8');
function parse(text){
 const lines=text.trimEnd().split(/\r?\n/);
 need(lines[0]==='# n11-s9-degree2-terminal-v1'&&
   lines[1]==='# board=11 perspective=original-first-player'&&
   lines[2]==='# empty_board=UNKNOWN'&&
   lines[3]==='# s9_win  canonical_s10_children  terminal_states_per_geometry',
   'invalid certificate metadata');
 return lines.slice(4).map(s=>{
  const m=/^([0-9a-f]{32}) ([0-9]+) ([0-9]+)$/.exec(s);
  need(!!m,'invalid certificate row');
  return {s9:m[1],leaves:Number(m[2]),states:Number(m[3])};
 });
}
function verify(rows,{terminal=true}={}){
 need(Array.isArray(rows)&&rows.length===14,'wrong certificate count');
 const plan=keys('n11-s5-pair-cover-20261026/s7-plan14-remaining.keys');
 need(plan.length===14&&new Set(plan).size===14,'plan changed');
 const plan8=new Set(plan.flatMap(h=>[...g.children(g.board(h,7))]));
 need(plan8.size===547,'plan boundary changed');
 const {win,loss}=base.inventory();
 need(win.size===2176&&loss.size===338,'prior proof inventory changed');
 const old5=JSON.parse(read('n11-s9-shared-plan14-20261027/certificate.json'));
 const old11=JSON.parse(read('n11-s9-shared-plan14-eleven-win-20261027/certificate.json'));
 const old9=[...old5.witnesses,...old11.witnesses].map(x=>x.s9_win);
 const win13='00000000000000821090a00000000020';
 const before=new Set([...win,win13,...g.reverse(old9)]);
 need(before.size===2315&&[...before].every(h=>!loss.has(h)),
   'previous proof-only S8 inventory changed');
 const oldS7=JSON.parse(read('n11-s7-terminal-loss12-20261024/certificate.json'));
 const loss10=new Set([...keys('n11-s8-to-s7-lift238-20261020/selected385.txt'),
   ...oldS7.s10_loss_cover39,...oldS7.s10_loss_cover12,
   ...keys('n11-s9-loss12-frontier-20261024/s10-loss12.keys'),
   ...lossCert.load().map(x=>x.s10)]);
 need(loss10.size===494,'prior S10 LOSS inventory changed');
 const loss9=g.reverse([...loss10]);
 need(loss9.size===4807,'prior proof-only S9 LOSS closure changed');
 const roots=new Set(),derived=new Set(),touched=new Set(),leaves10=new Set();
 let leafEdges=0,states=0;
 for(const row of rows){
  need(!roots.has(row.s9),'duplicate S9 root');roots.add(row.s9);
  need(Number.isSafeInteger(row.leaves)&&row.leaves>0&&
    Number.isSafeInteger(row.states)&&row.states>0,'invalid metadata');
  const b=g.board(row.s9,9);
  need(!loss9.has(row.s9),'S9 WIN/LOSS conflict: '+row.s9);
  const child=g.children(b),other=independent.children4(row.s9);
  need(same(child,other)&&child.size===row.leaves,
    'independent S9 universal boundary mismatch: '+row.s9);
  const parents=g.reverse([row.s9]);
  need(parents.size===9,'reverse S8 parent census changed');
  const selected=[...parents].filter(h=>plan8.has(h));
  need(selected.length===2,'not a degree-two plan witness: '+row.s9);
  for(const h of parents){
   need(g.children(g.board(h,8)).has(row.s9),'illegal S8->S9 incidence');
   need(!loss.has(h),'S8 WIN/LOSS conflict: '+h);
   derived.add(h);
   if(plan8.has(h)){
    need(independent.children4(h).has(row.s9),
      'independent S8->S9 geometry mismatch: '+h);
    touched.add(h);
   }
  }
  let subtotal=0;
  for(const h of child){
   need(!loss10.has(h),'S10 WIN/LOSS conflict: '+h);
   leaves10.add(h);leafEdges++;
   if(terminal){
    const a=g.solve10(h),d=independent.solve4(h);
    need(a.win&&d.win,'S10 terminal WIN counterexample: '+h);
    need(a.states===d.states&&a.legal===d.legal,
      'independent S10 terminal disagreement: '+h);
    subtotal+=a.states;
   }
  }
  if(terminal)need(subtotal===row.states,'S10 terminal-state mismatch: '+row.s9);
  states+=row.states;
 }
 need(leafEdges===217&&leaves10.size===215&&states===8511&&
   touched.size===26,'terminal proof census changed');
 const after=new Set([...before,...derived]);
 need([...after].every(h=>!loss.has(h)),'S8 WIN/LOSS conflict in union');
 const evaluate=set=>{
  let total=0,secured=0;const missing=new Set();
  for(const h of plan){
   for(const c of g.children(g.board(h,7))){
    total++;if(set.has(c))secured++;else missing.add(c);
   }
  }
  return {total,secured,missing:total-secured,distinctMissing:missing.size};
 };
 const previous=evaluate(before),updated=evaluate(after);
 need(previous.total===548&&previous.secured===68&&previous.missing===480&&
   previous.distinctMissing===480,'previous plan proof coverage changed');
 need(updated.missing<=previous.missing&&updated.distinctMissing===updated.missing,
   'new plan coverage inconsistent');
 const newProofs=[...derived].filter(h=>!before.has(h));
 const newPlan=[...touched].filter(h=>!before.has(h));
 need(updated.secured-previous.secured===newPlan.length,
   'new secured edges mismatch');
 return {format:'n11-s9-degree2-terminal-audit-v1',
   s9WinTerminalRoots:roots.size,s10WinLeafEdges:leafEdges,
   distinctS10WinLeaves:leaves10.size,
   terminalStatesPerGeometry:terminal?states:null,independentGeometries:terminal?2:0,
   s8WinDerived:derived.size,newS8WinProofs:newProofs.length,
   plan8Touched:touched.size,newlySecuredPlanEdges:newPlan.length,
   previous,updated,winLossConflicts:0,newS7Verdicts:0,newS5Verdicts:0,
   newTwoStoneClosures:0,emptyBoard:'UNKNOWN'};
}
if(require.main===module){
 const rows=parse(raw()),report=verify(rows);
 console.log(JSON.stringify(report,null,2));
 if(process.argv.includes('--negative')){
  const reject=(change,full=false)=>{
   const bad=structuredClone(rows);change(bad);let rejected=false;
   try{verify(bad,{terminal:full});}catch(_){rejected=true;}
   need(rejected,'tampered certificate accepted');
  };
  reject(r=>r.pop());
  reject(r=>r[1].s9=r[0].s9);
  reject(r=>r[0].s9=r[0].s9.slice(0,-1)+'f');
  reject(r=>r[0].leaves++);
  reject(r=>r[0].states++,true);
  let badHeader=raw().replace('empty_board=UNKNOWN','empty_board=WIN');
  let rejected=false;try{parse(badHeader);}catch(_){rejected=true;}
  need(rejected,'tampered header accepted');
  console.error('PASS six certificate mutation rejections');
 }
}
module.exports={parse,verify};
